<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)$err='Enter your name, valid email and password of at least 8 characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,phone,password_hash) VALUES(?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();$_SESSION['user_name']=$name;flash('Account created.');go('/MediHome/account.php');}catch(PDOException $e){$err='Email may already be registered.';}}}$title='Create Account | MediHome';require 'includes/header.php';?><div class="formbox"><span class="eyebrow">Join MediHome</span><h1>Create account</h1><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><form method="post"><div class="field"><label>Full name</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field"><label>Phone (optional)</label><input class="input" name="phone"></div><div class="field"><label>Password (8+ characters)</label><input class="input" name="password" type="password" minlength="8" required></div><button class="btn">Create account</button></form><p>Already registered? <a href="/MediHome/login.php">Log in</a></p></div><?php require 'includes/footer.php';?>